INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ver facturas de proveedor', 'supplierinvoice.read', (SELECT id FROM sub_modules WHERE code = 'PURCHASES'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'supplierinvoice.read');

